/**
 * Applies SQL migrations from ./drizzle (generated by drizzle-kit) and seeds
 * system reference data (roles, permissions, chart of accounts, settings row).
 * Idempotent — safe to run on every boot.
 */
import path from "node:path";
import fs from "node:fs";
import { sql } from "drizzle-orm";
import type { DB } from "./client";
import { seedSystemData } from "./seed";

function migrationsFolder() {
  const candidates = [path.resolve(process.cwd(), "drizzle"), path.resolve(__dirname, "../../../drizzle")];
  for (const c of candidates) if (fs.existsSync(path.join(c, "meta", "_journal.json"))) return c;
  throw new Error("Migrations folder not found. Run `npm run db:generate`.");
}

export async function runMigrations(db: DB, driver: "pg" | "pglite") {
  const folder = migrationsFolder();
  if (driver === "pg") {
    const { migrate } = await import("drizzle-orm/node-postgres/migrator");
    await migrate(db as never, { migrationsFolder: folder });
  } else {
    const { migrate } = await import("drizzle-orm/pglite/migrator");
    await migrate(db as never, { migrationsFolder: folder });
  }
  await db.execute(sql`select 1`);
  await seedSystemData(db);
}
